using OmniAI.Application.Authorization;
using OmniAI.Application.Concurrency;
using OmniAI.Application.Conversations.Persistence;
using OmniAI.Application.Tenants;
using OmniAI.Domain.Authorization;
using OmniAI.Domain.Conversations;
using OmniAI.Domain.Tenants;
using OmniAI.Domain.Users;

namespace OmniAI.Application.Conversations;

/// <summary>Send a reply to a customer, as the workspace.</summary>
/// <param name="ClientMessageId">
/// Generated by the composer before the request leaves the browser, so a retry
/// of a request whose response was lost cannot post the message twice. There is
/// deliberately no version here: see the remarks on the handler.
/// </param>
public sealed record ReplyToConversationCommand(
    Guid TenantId,
    Guid ConversationId,
    string? ClientMessageId,
    string? Text);

/// <summary>
/// Appending a reply written by a person.
/// </summary>
/// <remarks>
/// <strong>The sender is resolved here, from the authenticated request.</strong>
/// Not from the body, not from a header, not from anything a browser can choose.
/// A field naming who sent a message is a field worth forging, and the only
/// version of it this platform will store is the one the server already knows.
/// <para>
/// <strong>It refuses rather than taking the conversation over.</strong> Sending
/// a reply to a conversation the AI is still answering fails, and says so. The
/// alternative — inferring a takeover from a keystroke — means somebody who typed
/// in the wrong tab silently stopped an automation for a customer nobody is
/// watching. Two decisions, two actions.
/// </para>
/// <para>
/// <strong>It is conditioned on the idempotency key, not on the conversation's
/// version.</strong> A composer is a text box somebody has been typing in while
/// the conversation changed underneath them — a customer message arrived, a
/// colleague claimed it — and every one of those would invalidate a version they
/// were holding, so an <c>If-Match</c> here would reject replies for changes
/// that make no difference to whether the reply is correct. What must not happen
/// is the same reply landing twice, and the key prevents exactly that, enforced
/// by a unique index rather than by a check that could interleave.
/// </para>
/// <para>
/// <strong>It takes the conversation lock.</strong> Not for the idempotency —
/// the database handles that — but so a reply cannot interleave with a takeover
/// or with a turn that is still running, which is what keeps the transcript's
/// ingestion order a thing that can be reasoned about.
/// </para>
/// </remarks>
public sealed class ReplyToConversationHandler(
    TenantAuthorizer authorizer,
    TenantAccessGuard access,
    IConversationInboxStore store,
    IConversationLock conversationLock,
    IConversationRealtimeNotifier realtime,
    IOutboundReplyDispatcher dispatcher,
    TimeProvider clock)
{
    private readonly TenantAuthorizer _authorizer =
        authorizer ?? throw new ArgumentNullException(nameof(authorizer));

    private readonly TenantAccessGuard _access =
        access ?? throw new ArgumentNullException(nameof(access));

    private readonly IConversationInboxStore _store =
        store ?? throw new ArgumentNullException(nameof(store));

    private readonly IConversationLock _lock =
        conversationLock ?? throw new ArgumentNullException(nameof(conversationLock));

    private readonly IConversationRealtimeNotifier _realtime =
        realtime ?? throw new ArgumentNullException(nameof(realtime));

    private readonly IOutboundReplyDispatcher _dispatcher =
        dispatcher ?? throw new ArgumentNullException(nameof(dispatcher));

    private readonly TimeProvider _clock =
        clock ?? throw new ArgumentNullException(nameof(clock));

    /// <returns>
    /// The stored reply, or <see langword="null"/> when the caller is not
    /// entitled or no such conversation belongs to this workspace.
    /// </returns>
    /// <exception cref="PermissionDeniedException">
    /// A member of the workspace without <c>conversations.reply</c>.
    /// </exception>
    /// <exception cref="ConversationNotHandledByHumanException">
    /// The AI is still answering this conversation.
    /// </exception>
    /// <exception cref="DomainValidationException">
    /// The client message id or the text breaks a content rule.
    /// </exception>
    public async Task<ConversationMessageRecord?> HandleAsync(
        ReplyToConversationCommand command,
        CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(command);

        TenantId tenantId = TenantId.From(command.TenantId);
        ConversationId conversationId = ConversationId.From(command.ConversationId);

        // Validated before anything is authorised or locked, so a malformed
        // request never queues behind somebody else's provider call.
        ClientMessageId clientMessageId = ClientMessageId.Create(command.ClientMessageId);

        if (!await _authorizer
            .RequireAsync(tenantId, PlatformPermissions.ConversationsView, cancellationToken)
            .ConfigureAwait(false))
        {
            return null;
        }

        await _authorizer
            .RequireAsync(tenantId, PlatformPermissions.ConversationsReply, cancellationToken)
            .ConfigureAwait(false);

        UserId sender = _access.RequireCurrentUser();

        await using IAsyncDisposable hold = await _lock
            .AcquireAsync(conversationId.Value, cancellationToken)
            .ConfigureAwait(false);

        Versioned<Conversation>? found = await _store
            .FindForUpdateAsync(tenantId, conversationId, cancellationToken)
            .ConfigureAwait(false);

        if (found is null)
        {
            return null;
        }

        Conversation conversation = found.Value;

        // Read inside the lock, so it cannot have been handed back to the AI
        // between the check and the append.
        if (conversation.Handling != ConversationHandling.Human)
        {
            throw new ConversationNotHandledByHumanException();
        }

        HumanReplyOutcome outcome = await _store
            .AppendReplyAsync(
                conversation,
                sender,
                clientMessageId,
                command.Text ?? string.Empty,
                _clock.GetUtcNow(),
                cancellationToken)
            .ConfigureAwait(false);

        // A replayed duplicate announces nothing: the message it names was
        // already announced when it was first written, and every listener has
        // already re-read it.
        if (!outcome.WasAlreadyStored)
        {
            // Arranged before the announcement, so a colleague who sees the reply
            // appear is looking at something already queued for the customer
            // rather than at a message the platform has not yet decided to send.
            //
            // For website chat this does nothing at all: the visitor's browser is
            // already reading the transcript. For WhatsApp it queues a delivery
            // the outbound worker will send.
            await _dispatcher
                .DispatchAsync(
                    tenantId,
                    conversationId,
                    MessageId.From(outcome.Message.Id),
                    outcome.Message.Text,
                    cancellationToken)
                .ConfigureAwait(false);

            await _realtime
                .AnnounceQuietlyAsync(tenantId, conversationId, cancellationToken)
                .ConfigureAwait(false);
        }

        return outcome.Message;
    }
}
